class BatchedVeg implements VegBatch {
  readonly objects: THREE.Mesh[];
  private mesh: THREE.BatchedMesh;
  private ids: number[];
  constructor(w: World, geos: THREE.BufferGeometry[], maxInstances: number, material: THREE.Material, o: VegBatchOpts) {
    let verts = 0, idx = 0;
