+/** VEG-R02 review prototype: opaque, two-sided leaf silhouettes on the existing branch skeleton.
+ * Shared tree material; no alpha overdraw or rectangular card shadows. Selected only at the batch boundary.
+ */
+export function birchReferenceModel(variant: number, lod: Lod, continuous: boolean | 'outline' = 'outline'): Model {
+  const sp = BIRCHES[variant % 3], sk = growBroadleaf(sp);
+  const model = emitBroadleaf(sp, sk, lod, continuous);
+  model.leaves.dispose();
+  const t = new Tris();
+  // Identical deterministic shell at every distance, evenly thinned with wider leaves at lower LODs.
+  const count = lod === 'near' ? 84 : lod === 'mid' ? 48 : 28;
+  const leafScale = Math.sqrt(84 / count);
+  for (const k of sk.clusters) {
+    const r = mulberry32(Math.round(k.seed * 10000));
+    for (let i = 0; i < 84; i++) {
+      const u = (i + 0.5) / 84, y = 1 - 2 * u;
+      const az = i * 2.399963 + r() * 0.45, rad = Math.sqrt(1 - y * y);
+      const outward = new THREE.Vector3(Math.cos(az) * rad, y, Math.sin(az) * rad);
+      const spread = 0.72 + r() * 0.40;
+      const p = new THREE.Vector3(k.c.x + outward.x * k.r[0] * 1.65 * spread,
+        k.c.y + outward.y * k.r[1] * 1.65 * spread - 0.12,
+        k.c.z + outward.z * k.r[2] * 1.65 * spread);
