+      const tone = (0.76 + 0.25 * (y * 0.5 + 0.5) + r() * 0.14) * k.val;
+      const c = new THREE.Color().setRGB(tone * (0.94 + 0.08 * u), tone, tone * (0.76 + 0.13 * u));
+      if (Math.floor(i * count / 84) === Math.floor((i + 1) * count / 84)) continue;
+      const a = p.clone().addScaledVector(long, -length * 0.5);
+      const b = p.clone().addScaledVector(side, width).addScaledVector(UP, -length * 0.12);
+      const tip = p.clone().addScaledVector(long, length * 0.5);
+      const d = p.clone().addScaledVector(side, -width).addScaledVector(UP, -length * 0.12);
