// DEV-03: the estate-wide woodland. The woodland kit of the approved BOSLUST sample (branch-structured oak, beech,
// birch and Scots pine with four LODs; hazel and holly; ferns, bilberry, foxglove, lily of the valley, anemone,
// grasses; litter, verge stones, stumps; contact decals) now plants EVERY tree of the estate: the south forest, the
// north/east/west masses and glades, the garden specimens and the ring beyond the fence. Positions and trunk colliders
// are the layout's own (forest.ts, estate.ts, grounds.ts collect them here instead of drawing blob trees); the planner
// (woodlandPlan.ts) decides per site what grows under them. On top of the sample's recipe this adds the layers that
// make a forest rather than trees on a lawn: young trees in thickets, screens of bushes and saplings round the
// clearings (BOSLUST, the fire, the well, the shed, the wickerman and the golf tee are found, not seen from afar),
// fallen dead wood and mossy boulders.
//
// Render budget (phone guide ≤ 150 calls / PB01 camera triangles (docs/PERFORMANCE_BUDGET.md) at "low"): every tree and bush of the estate in ONE
// multi-draw batch (LOD by distance with hysteresis, per-instance frustum culling, trees drawn to 115 m, bushes to
// 50 m); every plant and litter leaf in one range-faded batch (shown within 11–24 m); stones and boulders in one;
// dead wood in one; contact decals in one instanced mesh. Five draw calls for all vegetation (instanced fallback: one
// per geometry in view).
import * as THREE from 'three';
import type { World } from '../interactions/world';
import type { Ctx } from './arch';
import type { TreeSpec } from './nature';
import { scatter, distToPolyline } from './nature';
import { planWoodland, stream, hash01, type WoodlandSite, type SourceTree, type SourceStump, type WoodlandPlan, type PlacedTree } from './woodlandPlan';
import { TreeBatches, PlantBatch, BOSLUST_SITE, DECAL, WOOD, stumpsV2, contactAt, inBackdrop, mat, TreeGrid } from './boslustSample';
import { inZone } from './boslustZone';
import { woodMats, rockModel, litterLeafModel, logModel, LEAF_TINT, type TreeSpecies, type PlantKind } from './woodkit';
import { CAPS } from '../core/caps';
import { TREE_LOD_PROFILE } from './vegetationLod';
import { ESTATE, WOODS, CLEARINGS, HILL_CUT, DRIVEWAY, WICKERMAN, GOLF_TEE, type Rect } from './layout';
import { FOREST_PATHS, terrainHeight } from './terrain';
import { ROUTE_LINES, vegetationClear, inWickermanClearing } from './footprints';
import { inRect } from './geom2d';

export type WoodGroup = 'forest' | 'mass' | 'garden' | 'outer';
interface Collected { t: SourceTree; group: WoodGroup }

const ROUTE = (id: string) => ROUTE_LINES.find((r) => r.id === id)!.pts;
/** Walked lines in the south forest: the forest network, the wickerman loop and the golf spur. */
const SOUTH_PATHS = [...FOREST_PATHS, ROUTE('wickermanLoop'), ROUTE('wickermanSide'), ROUTE('golfSpur')];
const NORTH_PATHS = ROUTE_LINES.filter((r) => r.id !== 'wickermanLoop' && r.id !== 'wickermanSide' && r.id !== 'golfSpur').map((r) => r.pts);
const pathDist = (paths: readonly (readonly (readonly [number, number])[])[], x: number, z: number) => { let d = Infinity; for (const p of paths) d = Math.min(d, distToPolyline(x, z, p)); return d; };
const inCut = (x: number, z: number) => x > HILL_CUT.x0 - 1.5 && x < HILL_CUT.x1 + 1.5 && z > HILL_CUT.z0 - 1 && z < 24;
const inClearing = (x: number, z: number, m = 0) => CLEARINGS.some((c) => Math.hypot(x - c.x, z - c.z) < c.r + m);
/** Thickets vs open stands: a slow field (−1 … 1) so density varies in pockets, not uniformly. */
const thicket = (x: number, z: number) => Math.sin(x * 0.083 + Math.sin(z * 0.051) * 1.7) * Math.cos(z * 0.071 - x * 0.019) + 0.35 * Math.sin(x * 0.21 + z * 0.17);
const AREA0 = 50 * 47.4; // the BOSLUST zone the planner's defaults were tuned for
/** Fallen-log sizes (length, radius): baked per variant, instances only scale uniformly. */
const LOGS: [number, number][] = [[2.4, 0.17], [3.2, 0.21], [4.1, 0.26], [2.9, 0.19]];

/** Planted area of the south forest (outside the BOSLUST zone, which keeps its approved plan). */
const SOUTH_SITE: WoodlandSite = {
  seed: 3101,
  bounds: { x0: 0.8, x1: ESTATE.w - 0.8, z0: 0.8, z1: ESTATE.forestEdge - 0.5 },
  inArea: (x, z) => z < ESTATE.forestEdge - 0.5 && !inZone(x, z),
  keepClear: (x, z) => inCut(x, z) || inClearing(x, z, -1.2) || inWickermanClearing(x, z, -0.5) || distToPolyline(x, z, DRIVEWAY) < 3.4 || !vegetationClear(x, z, 'small'),
  paths: SOUTH_PATHS,
  ground: terrainHeight,
};
const massSite = (m: Rect & { id: string }, i: number): WoodlandSite => ({
  seed: 3200 + i * 17,
  bounds: { x0: m.x0, x1: m.x1, z0: m.z0, z1: m.z1 },
  inArea: (x, z) => inRect(x, z, m),
  keepClear: (x, z) => !vegetationClear(x, z, 'small'),
  paths: NORTH_PATHS,
  ground: terrainHeight,
});
/** The old nest-box oak on the lake's east shore (grounds.ts mounts the box ON its trunk with woodkit.trunkAt). */
export const NEST_OAK = { x: 80.2, z: 148.6, species: 'oak' as const, v: 1, yaw: 0.9 };
/** Trees only (garden specimens, the ring beyond the fence): no understory is planned. */
const TREES_ONLY: WoodlandSite = { seed: 3300, bounds: { x0: 0, x1: 12, z0: 0, z1: 12 }, inArea: () => false, keepClear: () => true, paths: [], ground: terrainHeight, heroes: [NEST_OAK] };

export class EstateWoods {
  private trees: Collected[] = [];
  private stumps: SourceStump[] = [];
  /** Called by the Vegetation capture hook for every tree of the layout (except the clipped garden cypresses). */
  addTree(t: TreeSpec, chunk: string) {
    const group: WoodGroup = chunk === 'outer' ? 'outer' : chunk === 'garden' ? 'garden' : chunk.startsWith('w') ? 'mass' : 'forest';
    const y = t.y ?? terrainHeight(t.x, t.z);
    this.trees.push({ t: { x: t.x, z: t.z, y, h: t.h, r: t.r, kind: t.kind, hue: t.hue }, group });
  }
  /** Garden planting (DEV-03): woodland-kit plants on the lawns and in the beds, drawn in the plants batch. */
  private garden: { kind: PlantKind; v: number; x: number; z: number; s: number; y?: number; show?: number }[] = [];
  addPlant(kind: PlantKind, v: number, x: number, z: number, s = 1, y?: number, show?: number) { this.garden.push({ kind, v, x, z, s, y, show }); }
  /** A stump of the forest layout (its collider exists and is never moved). */
  addStump(s: SourceStump) { this.stumps.push(s); }
  /** Trunk positions of the woodland (forest floor colouring under the crowns). */
  points(): [number, number][] { return this.trees.filter((c) => c.group === 'forest' || c.group === 'mass').map((c) => [c.t.x, c.t.z]); }
/**
 * Holly: a compact evergreen — a short stem and side branches under an irregular, upward-tapering mass of spiky,
 * glossy clumps (lighter, warmer tops, so it reads as leaves catching light rather than a dark blob), with a few
 * berry clusters. Three layouts (height, fullness).
 */
export function hollyModel(variant: number, lod: Lod): Model {
  const v = variant % 3, r = mulberry32(9203 + v * 71), near = lod === 'near';
  const rnd = (a: number, b: number) => a + r() * (b - a);
  const Hh = [1.6, 2.0, 1.3][v], n = 10 + v * 2;
  const wood: THREE.BufferGeometry[] = [taperTube([[0, -0.1, 0], [0.03, Hh * 0.4, 0.02], [0.02, Hh * 0.8, -0.02]], [0.07, 0.05, 0.03], { radial: near ? 6 : 4, rows: 3 })];
  const clusters: Cluster[] = [];
  for (let i = 0; i < n; i++) {
    const t = i / (n - 1), y = 0.3 + t * Hh * 0.85, rad = (1 - t) * 0.5 + 0.08, a = i * 2.39996 + rnd(-0.5, 0.5);
    const c = new THREE.Vector3(Math.cos(a) * rad * rnd(0.7, 1.2), y, Math.sin(a) * rad * rnd(0.7, 1.2));
    if (near && t < 0.7) wood.push(taperTube([[0, y - 0.15, 0], [c.x * 0.6, y - 0.05, c.z * 0.6], [c.x, y, c.z]], [0.025, 0.018, 0.01], { radial: 3, rows: 2 }));
    const s = (0.24 + (1 - t) * 0.18) * rnd(0.85, 1.15);
    clusters.push({ c, r: [s * 1.05, s * rnd(0.85, 1.0), s], seed: v * 7 + i * 4.3, amp: 0.26, flat: 0.85, val: rnd(0.95, 1.15), spiky: true });
  }
  const centre = new THREE.Vector3(0, Hh * 0.5, 0);
  const ks = lod === 'far' ? largest(clusters, 8) : clusters;
  const leafGeos = cullBuried(ks.map((k) => clusterGeo(k, lod, centre, Hh * 0.6, 0.35)), ks);
  // glossy holly: tops markedly lighter than the shaded sides (vertex colour), so the form reads in value
  for (const g of leafGeos) {
    const c = g.attributes.color as THREE.BufferAttribute, nn = g.attributes.normal as THREE.BufferAttribute;
    for (let i = 0; i < c.count; i++) { const k = 1 + 0.35 * THREE.MathUtils.smoothstep(nn.getY(i), 0.3, 0.95); c.setXYZ(i, c.getX(i) * k, c.getY(i) * k, c.getZ(i) * k * 0.95); }
  }
  // berries (near only): small red clusters on the outside. Vertex colour = red ÷ the holly leaf tint, so the
  // instance colour (the leaf tint) brings them back to red.
  if (near) {
    const tint = new THREE.Color('#46663a'), red = new THREE.Color('#b0201c');
    for (let i = 0; i < 6; i++) {
      const k = clusters[1 + Math.floor(r() * (clusters.length - 3))], a = r() * Math.PI * 2;
      const p = k.c.clone().add(new THREE.Vector3(Math.cos(a) * k.r[0] * 0.95, rnd(-0.1, 0.2) * k.r[1], Math.sin(a) * k.r[2] * 0.95));
      for (let b = 0; b < 3; b++) {
        const g0 = new THREE.IcosahedronGeometry(0.03, 0).translate(p.x + (b - 1) * 0.035, p.y - (b % 2) * 0.03, p.z + (b % 2) * 0.03);
        g0.deleteAttribute('uv');
        leafGeos.push(paint(mergeVertices(g0), () => [red.r / tint.r, red.g / tint.g, red.b / tint.b])); // indexed, like the clusters
        g0.dispose();
      }
    }
  }
  return { wood: mergeParts(wood.map((g) => barkCol(paint(g, 0.8), BARK.smooth))), leaves: mergeParts(leafGeos.map((g) => foliageUV(g, 0.7))) };
}
export function bushModel(species: BushSpecies, variant: number, lod: Lod): Model {
  return species === 'hazel' ? hazelModel(variant, lod) : hollyModel(variant, lod);
}

// ------------------------------------------------------------------------------------------------ rocks
/**
 * Rock: the convex hull of a few jittered points on a squashed, slightly tilted ellipsoid — a handful of broad,
 * deliberate planes. Normals creased at ~32° so shallow transitions soften while real edges stay crisp. Vertex
 * colour: moss on upward faces near the top, darker toward the ground (contact).
 */
export function rockModel(seed: number): THREE.BufferGeometry {
  const r: Rng = mulberry32(seed);
  const pts: THREE.Vector3[] = [];
  const n = 11 + Math.floor(r() * 4), tilt = (r() - 0.5) * 0.35;
  for (let i = 0; i < n; i++) {
    const u = r() * Math.PI * 2, v = Math.acos(2 * r() - 1);
    let x = Math.sin(v) * Math.cos(u), y = Math.cos(v), z = Math.sin(v) * Math.sin(u);
    y = y > 0 ? y * (0.55 + r() * 0.25) : y * 0.4; // flatter top, buried bottom

/** Lily of the valley: two or three broad upright leaves and an arching stem of tiny white bells. */
export function lilyModel(variant = 0): THREE.BufferGeometry {
  const v = variant % 3, r = mulberry32(91 + v * 29), t = new Tris();
  const nl = v === 1 ? 3 : 2, nb = [5, 7, 4][v], l0 = C('#3c6a2e'), l1 = C('#6b9a48'), white = C('#f2f0e4');
  for (let i = 0; i < nl; i++) {
    const a = (i / nl) * Math.PI * 2 + r() * 0.6;
    leafShape(t, V(0, 0, 0), V(Math.cos(a), 0, Math.sin(a)), 0.2 + r() * 0.04, 0.045, 0.02, l0, l1, 4, 0.85);
  }
  const a = r() * Math.PI * 2, d = V(Math.cos(a), 0, Math.sin(a));
  const pts = [V(0, 0, 0), d.clone().multiplyScalar(0.02).add(V(0, 0.13, 0)), d.clone().multiplyScalar(0.07).add(V(0, 0.17, 0)), d.clone().multiplyScalar(0.11).add(V(0, 0.14, 0))];
  stem(t, pts, 0.003, C('#5b8040'));
  for (let k = 0; k < nb; k++) {
    const u = 0.4 + (k / nb) * 0.6, i = Math.min(2, Math.floor(u * 3)), p = pts[i].clone().lerp(pts[i + 1], u * 3 - i);
    bell(t, p.add(V(0, -0.01, 0)), V(0, -1, 0), 0.016, 0.009, white, white, 5);
  }
  return t.build(0.4);
}

/** Wood anemone: one, three or five white stars over a whorl of three lobed leaves. */
export function anemoneModel(variant = 0): THREE.BufferGeometry {
  const v = variant % 3, r = mulberry32(101 + v * 31), t = new Tris();
  const n = [1, 3, 5][v], white = C('#f6f3ea'), eye = C('#e8c94a'), green = C('#4d7a34');
  for (let i = 0; i < n; i++) {
    const a = r() * Math.PI * 2, rr = i ? 0.04 + r() * 0.05 : 0, h = 0.1 + r() * 0.05;
    const b = V(Math.cos(a) * rr, 0, Math.sin(a) * rr), top = b.clone().add(V(0, h, 0));
    stem(t, [b, top], 0.003, green);
    for (let k = 0; k < 3; k++) { const la = a + k * 2.1; leafShape(t, b.clone().add(V(0, h * 0.55, 0)), V(Math.cos(la), 0, Math.sin(la)), 0.04, 0.02, 0.005, green, green, 1); }
    for (let k = 0; k < 6; k++) { // six petals around a yellow eye
      const pa = (k / 6) * Math.PI * 2 + a, d = V(Math.cos(pa), 0, Math.sin(pa)), s = V(-d.z, 0, d.x);
      t.tri(top, top.clone().addScaledVector(d, 0.03).addScaledVector(s, 0.011), top.clone().addScaledVector(d, 0.03).addScaledVector(s, -0.011), eye, white, white);
    }
  }
  return t.build(0.7);
}

export function plantModel(kind: PlantKind, variant: number): THREE.BufferGeometry {
  return kind === 'fern' ? fernModel(variant) : kind === 'grass' ? grassModel(variant) : kind === 'bilberry' ? bilberryModel(variant) : kind === 'foxglove' ? foxgloveModel(variant) : kind === 'lily' ? lilyModel(variant) : anemoneModel(variant);
}

/**
 * DEV-04B timber family: a fallen / cut log as ONE CLOSED solid (no open tube ends, no hollow branch stub). Fissured
 * bark body, slightly bent, tapering; both ends are sawn faces built on the body's own end ring (shared vertices, so
 * the end grain can never leave a gap or show the inside), pale sapwood with a darker heart and a bark rim; the
 * branch stub is capped. Lies along local +x from 0 to `len`, radius `rad`, its underside a little sunk. Colours are
 * baked (keepColor): bark darker toward the ground, pale end grain.
 * DEV-03 had the same silhouette but an open-ended stub and separate end discs that could gap from the body.
 */
export function logModel(seed: number, len = 3, rad = 0.22, o: { stub?: boolean; radial?: number } = {}): THREE.BufferGeometry {
  const r = mulberry32(seed);
  const bend = (r() - 0.5) * 0.3, sag = rad * 0.25, radial = o.radial ?? 7;
  // built upright like a trunk (the tube's frames give outward-facing triangles along +y), then laid along +x
  const pts: P3[] = [0, 0.33, 0.66, 1].map((t) => [sag * Math.sin(t * Math.PI), t * len, bend * Math.sin(t * Math.PI) * len * 0.15]);
  const rr = [rad, rad * (0.95 + r() * 0.03), rad * (0.86 + r() * 0.04), rad * 0.78];
  const body = taperTube(pts, rr, { radial, rows: 4, vScale: 1.2 });
  const parts: THREE.BufferGeometry[] = [body];
  if (o.stub !== false && len > 0.8) {
    const sp: P3[] = [[-rad * 0.6, len * 0.4, 0], [-rad * 1.9, len * 0.47, rad * 0.7]];
    const stub = taperTube(sp, [rad * 0.34, rad * 0.16], { radial: 5, rows: 2 });
    parts.push(stub, capRing(stub, 'start', 5), capRing(stub, 'end', 5)); // closed at both ends (its base sits inside the log)
  }
  parts.push(capRing(body, 'start', radial), capRing(body, 'end', radial));
  for (const g of parts) {
    g.rotateZ(-Math.PI / 2).translate(0, rad * 0.7, 0); // +y → +x; x (sag) → −y
    const ix = g.index!.array as Uint16Array | Uint32Array; // taperTube winds inward for this frame: face the triangles out
    for (let t = 0; t < ix.length; t += 3) { const a = ix[t + 1]; ix[t + 1] = ix[t + 2]; ix[t + 2] = a; }
    g.computeVertexNormals();
  }
  paint(body, (p) => { const k = 0.62 + 0.38 * THREE.MathUtils.smoothstep(p.y, 0, rad * 1.4); return [k, k * 0.97, k * 0.92]; });
  barkCol(body, BARK.fissured);
  for (const g of parts.slice(1)) if (!g.attributes.color) { paint(g, 0.85); barkCol(g, BARK.fissured); }
  const g = mergeParts(parts);
  g.userData.keepColor = true;
  g.computeBoundingSphere();
  return g;
}
