 * branches are preserved so the layout and attachment surfaces remain compatible. */
export function birchReferenceModel(variant: number, lod: Lod, continuous: boolean | 'outline' = 'outline'): Model {
  const sp = BIRCHES[variant % 3], sk = growBroadleaf(sp);
  const model = emitBroadleaf(sp, sk, lod, continuous);
  model.leaves.dispose();
  const parts: THREE.BufferGeometry[] = [];
  const centre = sk.clusters.reduce((a, k) => a.add(k.c), new THREE.Vector3()).divideScalar(sk.clusters.length);
  // Three shared core planes persist at every LOD; two extra planes break up the close silhouette.
  const planes = lod === 'near' ? 5 : 3;
  for (const k of sk.clusters) {
    const r = mulberry32(Math.round(k.seed * 10000));
    const yaw = r() * Math.PI * 2;
    for (let i = 0; i < planes; i++) {
      const angle = yaw + i * Math.PI / 3;
      const side = new THREE.Vector3(Math.cos(angle), 0, Math.sin(angle));
      const up = new THREE.Vector3(Math.sin(angle) * 0.25, 1, -Math.cos(angle) * 0.25).normalize();
      const c = k.c.clone().add(new THREE.Vector3((r() - .5) * .18, -.18 + (r() - .5) * .16, (r() - .5) * .18));
      const width = (k.r[0] + k.r[2]) * 1.45, height = k.r[1] * 4.4;
      const pts = [c.clone().addScaledVector(side, -width).addScaledVector(up, -height),
        c.clone().addScaledVector(side, width).addScaledVector(up, -height),
        c.clone().addScaledVector(side, width).addScaledVector(up, height),
        c.clone().addScaledVector(side, -width).addScaledVector(up, height)];
      const g = new THREE.BufferGeometry();
      g.setAttribute('position', new THREE.Float32BufferAttribute(pts.flatMap(p => p.toArray()), 3));
      g.setAttribute('uv', new THREE.Float32BufferAttribute([128,0,129,0,129,1,128,1], 2));
      g.setIndex([0,1,2,0,2,3]);
      const normals: number[] = [], colors: number[] = [];
      for (const p of pts) {
        const n = p.clone().sub(centre).normalize().lerp(UP, .55).normalize();
        normals.push(n.x,n.y,n.z);
        const top = THREE.MathUtils.clamp((p.y - (centre.y - 4)) / 8, 0, 1);
        const value = (.76 + .34 * top) * k.val;
        colors.push(value * (.94 + .1 * top), value, value * (.94 - .16 * top));
      }
      g.setAttribute('normal',new THREE.Float32BufferAttribute(normals,3));
      g.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));
      parts.push(twoSided(g));
    }
  }
  model.leaves = mergeParts(parts);
  return model;
}

